INSERT INTO `help_faq` VALUES (1, 'AI 答疑和拍照搜题有什么区别？', 'AI 答疑适合对已选题目进行多轮追问讲解；拍照搜题适合通过拍照或输入题干快速匹配答案与解析。题目讲解请优先使用 AI Tab 的「AI 答疑」。', 1, 1, '2026-08-21 09:36:30', '2026-08-21 09:36:30');
INSERT INTO `help_faq` VALUES (2, '免费用户每天可以使用多少次 AI 和搜题？', '免费用户每日 AI 答疑与拍照搜题各有次数上限，具体以会员中心权益说明为准。开通 AI 至尊会员后可享受更高或无限次权益。', 2, 1, '2026-08-21 09:36:30', '2026-08-21 09:36:30');
INSERT INTO `help_faq` VALUES (3, '错题本里的题会自动同步吗？', '交卷后做错的题目会自动收录到错题本。登录状态下数据会同步到云端，换设备登录后可继续查看与复习。', 3, 1, '2026-08-21 09:36:30', '2026-08-21 09:36:30');
INSERT INTO `help_faq` VALUES (4, '如何修改年级、学科或教材版本？', '可在「我的 → 设置 → 修改学习计划」中调整年级、学科和教材版本，保存后会同步更新首页推荐与刷题筛选。', 4, 1, '2026-08-21 09:36:30', '2026-08-21 09:36:30');
INSERT INTO `help_faq` VALUES (5, '会员开通后多久生效？支付失败怎么办？', '支付成功后会员权益即时生效。若扣款成功但页面未更新，请稍后在「我的 → 会员中心」刷新查看；仍异常请在本页提交反馈并附上支付截图。', 5, 1, '2026-08-21 09:36:30', '2026-08-21 09:36:30');
