INSERT INTO `tb_question` VALUES (1, 'rational-numbers-q01', 1, 1, '下列各数中，属于负数的是（ ）', '单选题', '简单', 'A', '负数是小于 0 的数。选项中 -3 小于 0，是负数；0 既不是正数也不是负数；1 和 2 都大于 0，是正数。因此本题选 A。', 'https://tu.mianyazuju.com/2026/08/26/0dc8ad3e-cb5d-4395-a8e2-cd9369f9e47c.mp4', 'https://tu.mianyazuju.com/2026/08/26/daa60365-45b7-4254-8bfb-69c0d65f73f0.jpg', '00:18', '王老师', '本题讲解视频：下列各数中，属于负数的是（ ）', '[{\"label\":\"A\",\"value\":\"-3\"},{\"label\":\"B\",\"value\":\"0\"},{\"label\":\"C\",\"value\":\"1\"},{\"label\":\"D\",\"value\":\"2\"}]', '[\"#负数定义\",\"#有理数\"]', 1, 1, '2026-08-05 10:36:26', '2026-08-26 10:48:32');
INSERT INTO `tb_question` VALUES (2, 'rational-numbers-q02', 1, 1, '计算 (-2) + (-3) 的结果是（ ）', '单选题', '简单', 'B', '同号两数相加，取相同符号，并把绝对值相加。(-2)+(-3)=-(2+3)=-5，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/59c066b1-4734-49e9-a077-f0371a8ae206.mp4', 'https://tu.mianyazuju.com/2026/08/26/45bdb6e2-b136-4a1e-82bd-785438d83275.jpg', '00:18', '王老师', '本题讲解视频：计算 (-2) + (-3) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"-1\"},{\"label\":\"B\",\"value\":\"-5\"},{\"label\":\"C\",\"value\":\"5\"},{\"label\":\"D\",\"value\":\"1\"}]', '[\"#有理数加法\",\"#同号相加\"]', 2, 1, '2026-08-05 10:36:26', '2026-08-26 10:48:48');
INSERT INTO `tb_question` VALUES (3, 'rational-numbers-q03', 1, 2, '一个数的绝对值是5，则这个数是（ ）', '单选题', '中等', 'C', '绝对值等于 5 的数有两个：5 和 -5，即 ±5。故选 C。', 'https://tu.mianyazuju.com/2026/08/26/e9c941a2-0106-459b-ae10-562d35f506af.mp4', 'https://tu.mianyazuju.com/2026/08/26/ec0d005f-3b03-45e0-b28b-54fc729efaf3.jpg', '00:18', '王老师', '本题讲解视频：一个数的绝对值是5，则这个数是（ ）', '[{\"label\":\"A\",\"value\":\"5\"},{\"label\":\"B\",\"value\":\"-5\"},{\"label\":\"C\",\"value\":\"±5\"},{\"label\":\"D\",\"value\":\"0\"}]', '[\"#绝对值\",\"#有理数\"]', 3, 1, '2026-08-05 10:36:26', '2026-08-26 10:48:59');
INSERT INTO `tb_question` VALUES (4, 'polynomial-q01', 2, 4, '下列各式中，是单项式的是（ ）', '单选题', '简单', 'A', '单项式是数与字母的积，不含加减运算。3x 是单项式，x+1、x/y、x-2 都含加减或除法，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/debb3058-0d6e-4cb1-8fb3-d5a5f87fcf9f.mp4', 'https://tu.mianyazuju.com/2026/08/26/d5654782-c3d2-4aeb-b295-efbd26f546a8.jpg', '00:18', '王老师', '本题讲解视频：下列各式中，是单项式的是（ ）', '[{\"label\":\"A\",\"value\":\"3x\"},{\"label\":\"B\",\"value\":\"x+1\"},{\"label\":\"C\",\"value\":\"x/y\"},{\"label\":\"D\",\"value\":\"x-2\"}]', '[\"#整式\",\"#单项式\"]', 1, 1, '2026-08-05 10:52:21', '2026-08-26 10:48:27');
INSERT INTO `tb_question` VALUES (5, 'polynomial-q02', 1, 5, '计算 3a + 2a 的结果是（ ）', '单选题', '简单', 'B', '同类项合并时系数相加：3a+2a=(3+2)a=5a，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/ef20364a-5ea0-41b9-8a16-ea5e049cad13.mp4', 'https://tu.mianyazuju.com/2026/08/26/015f10de-d017-498c-9011-dbc114ea1857.jpg', '00:18', '王老师', '本题讲解视频：计算 3a + 2a 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"5\"},{\"label\":\"B\",\"value\":\"5a\"},{\"label\":\"C\",\"value\":\"6a\"},{\"label\":\"D\",\"value\":\"a\"}]', '[\"#整式加减\"]', 2, 1, '2026-08-05 10:52:21', '2026-08-26 10:48:43');
INSERT INTO `tb_question` VALUES (6, 'mechanics-q01', 3, 6, '下列物理量中，属于矢量的是（ ）', '单选题', '中等', 'C', '矢量既有大小又有方向。速度是矢量；质量、时间、温度只有大小没有方向，是标量，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/f8c699a4-ee16-4d6f-b5cc-b92bbe81b16f.mp4', 'https://tu.mianyazuju.com/2026/08/26/8b6d7437-d530-49ed-bb09-e5eb5e39eaf8.jpg', '00:18', '主讲老师', '本题讲解视频：下列物理量中，属于矢量的是（ ）', '[{\"label\":\"A\",\"value\":\"质量\"},{\"label\":\"B\",\"value\":\"时间\"},{\"label\":\"C\",\"value\":\"速度\"},{\"label\":\"D\",\"value\":\"温度\"}]', '[\"#矢量\",\"#力学基础\"]', 1, 1, '2026-08-05 10:52:21', '2026-08-26 10:48:30');
INSERT INTO `tb_question` VALUES (7, 'mechanics-q02', 3, 6, '物体所受重力方向是（ ）', '单选题', '简单', 'B', '重力方向始终竖直向下，指向地心附近方向，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/13e37399-05cf-4edd-9229-f51989b3175a.mp4', 'https://tu.mianyazuju.com/2026/08/26/87360004-d2ff-4220-b0c6-38205ca42e4c.jpg', '00:18', '王老师', '本题讲解视频：物体所受重力方向是（ ）', '[{\"label\":\"A\",\"value\":\"水平向前\"},{\"label\":\"B\",\"value\":\"竖直向下\"},{\"label\":\"C\",\"value\":\"竖直向上\"},{\"label\":\"D\",\"value\":\"斜向下\"}]', '[\"#重力\"]', 2, 1, '2026-08-05 10:52:21', '2026-08-26 10:48:45');
INSERT INTO `tb_question` VALUES (8, 'rational-numbers-q04', 1, 2, '|-3| 的值是（ ）', '单选题', '简单', 'B', '绝对值表示数到原点的距离，不含符号。|-3| 表示 -3 到原点的距离为 3，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/18a3eaa2-5214-4230-ae0b-710ec17b9990.mp4', 'https://tu.mianyazuju.com/2026/08/26/faf5f1e7-7c8b-4589-9086-041984d63f8c.jpg', '00:18', '王老师', '本题讲解视频：|-3| 的值是（ ）', '[{\"label\":\"A\",\"value\":\"-3\"},{\"label\":\"B\",\"value\":\"3\"},{\"label\":\"C\",\"value\":\"±3\"},{\"label\":\"D\",\"value\":\"0\"}]', '[\"#绝对值\",\"#有理数\"]', 4, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:01');
INSERT INTO `tb_question` VALUES (9, 'rational-numbers-q05', 1, 3, '计算 5 + (-8) 的结果是（ ）', '单选题', '简单', 'C', '正数加负数，取绝对值较大的数的符号，并用较大绝对值减较小绝对值：5+(-8)=-(8-5)=-3，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/e75e56b1-ff2c-4480-85b0-565acdf5f225.mp4', 'https://tu.mianyazuju.com/2026/08/26/597f4826-e0b0-43b1-9ae7-3e1600684635.jpg', '00:18', '王老师', '本题讲解视频：计算 5 + (-8) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"13\"},{\"label\":\"B\",\"value\":\"3\"},{\"label\":\"C\",\"value\":\"-3\"},{\"label\":\"D\",\"value\":\"-13\"}]', '[\"#有理数加法\"]', 5, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:09');
INSERT INTO `tb_question` VALUES (10, 'rational-numbers-q06', 1, 1, '下列说法正确的是（ ）', '单选题', '中等', 'D', '0 既不是正数也不是负数；正数都大于 0；负数都小于 0。只有 D 正确，故选 D。', 'https://tu.mianyazuju.com/2026/08/26/27c7ca7e-26a7-4774-86b8-6c21c37a6671.mp4', 'https://tu.mianyazuju.com/2026/08/26/46c831eb-61ef-4136-96c7-9eb4a28fee9c.jpg', '00:18', '王老师', '本题讲解视频：下列说法正确的是（ ）', '[{\"label\":\"A\",\"value\":\"0是正数\"},{\"label\":\"B\",\"value\":\"0是负数\"},{\"label\":\"C\",\"value\":\"正数小于0\"},{\"label\":\"D\",\"value\":\"负数小于0\"}]', '[\"#有理数分类\"]', 6, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:18');
INSERT INTO `tb_question` VALUES (11, 'rational-numbers-q07', 1, 3, '计算 (-4) - (-6) 的结果是（ ）', '单选题', '中等', 'B', '减去一个负数等于加上它的相反数：(-4)-(-6)=(-4)+6=2，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/330bdc51-d707-4a3a-bc5b-976a00c66617.mp4', 'https://tu.mianyazuju.com/2026/08/26/14ef1972-1b95-4a84-9d1a-ef25519b2278.jpg', '00:18', '王老师', '本题讲解视频：计算 (-4) - (-6) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"-10\"},{\"label\":\"B\",\"value\":\"2\"},{\"label\":\"C\",\"value\":\"-2\"},{\"label\":\"D\",\"value\":\"10\"}]', '[\"#有理数减法\"]', 7, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:24');
INSERT INTO `tb_question` VALUES (12, 'rational-numbers-q08', 1, 2, '数轴上，点 A 表示 -2，点 B 表示 3，则 A、B 两点间的距离是（ ）', '单选题', '中等', 'C', '数轴上两点距离等于两数差的绝对值：|3-(-2)|=|5|=5，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/56f06ce3-ff2f-49b9-9c65-0ba0a4994404.mp4', 'https://tu.mianyazuju.com/2026/08/26/9f2fd707-a966-4be2-95af-8e41e5d789da.jpg', '00:18', '王老师', '本题讲解视频：数轴上，点 A 表示 -2，点 B 表示 3，则 A、B 两点间的距离是（ ）', '[{\"label\":\"A\",\"value\":\"1\"},{\"label\":\"B\",\"value\":\"-1\"},{\"label\":\"C\",\"value\":\"5\"},{\"label\":\"D\",\"value\":\"-5\"}]', '[\"#数轴\",\"#距离\"]', 8, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:27');
INSERT INTO `tb_question` VALUES (13, 'rational-numbers-q09', 1, 3, '计算 (-2) × 3 的结果是（ ）', '单选题', '简单', 'A', '异号两数相乘得负，并把绝对值相乘：(-2)×3=-6，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/60a0bfc2-5845-42b0-877c-bea36441e5f5.mp4', 'https://tu.mianyazuju.com/2026/08/26/d825a764-7ee0-43e6-83fb-6da80577dd06.jpg', '00:18', '王老师', '本题讲解视频：计算 (-2) × 3 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"-6\"},{\"label\":\"B\",\"value\":\"6\"},{\"label\":\"C\",\"value\":\"-5\"},{\"label\":\"D\",\"value\":\"5\"}]', '[\"#有理数乘法\"]', 9, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:30');
INSERT INTO `tb_question` VALUES (14, 'rational-numbers-q10', 1, 3, '计算 (-12) ÷ (-3) 的结果是（ ）', '单选题', '简单', 'B', '同号两数相除得正，并把绝对值相除：(-12)÷(-3)=4，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/0a4c7487-e8d0-404a-aa7b-8abb3d9bb81f.mp4', 'https://tu.mianyazuju.com/2026/08/26/a73c8e15-b501-4391-b145-0d6d8dff9e7b.jpg', '00:18', '王老师', '本题讲解视频：计算 (-12) ÷ (-3) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"-4\"},{\"label\":\"B\",\"value\":\"4\"},{\"label\":\"C\",\"value\":\"-36\"},{\"label\":\"D\",\"value\":\"36\"}]', '[\"#有理数除法\"]', 10, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:33');
INSERT INTO `tb_question` VALUES (15, 'rational-numbers-q11', 1, 1, '若 a 的相反数是 5，则 a 的值是（ ）', '单选题', '简单', 'A', '若 a 的相反数是 5，则 a=-5，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/a64bd2ab-319c-4130-b60c-7c29a7f2f031.mp4', 'https://tu.mianyazuju.com/2026/08/26/f982ba44-dc7e-49ac-9a6b-88e62cc07277.jpg', '00:18', '王老师', '本题讲解视频：若 a 的相反数是 5，则 a 的值是（ ）', '[{\"label\":\"A\",\"value\":\"-5\"},{\"label\":\"B\",\"value\":\"5\"},{\"label\":\"C\",\"value\":\"±5\"},{\"label\":\"D\",\"value\":\"0\"}]', '[\"#相反数\"]', 11, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:36');
INSERT INTO `tb_question` VALUES (16, 'rational-numbers-q12', 1, 1, '已知 a+b=0，则 a 与 b 的关系是（ ）', '单选题', '简单', 'C', '两数之和为 0，则它们互为相反数，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/ff09f3b9-3ecd-40c0-b7fe-250e41a7f080.mp4', 'https://tu.mianyazuju.com/2026/08/26/5680c003-42af-4af6-a8f3-fa4df4fb20bc.jpg', '00:18', '王老师', '本题讲解视频：已知 a+b=0，则 a 与 b 的关系是（ ）', '[{\"label\":\"A\",\"value\":\"相等\"},{\"label\":\"B\",\"value\":\"互为倒数\"},{\"label\":\"C\",\"value\":\"互为相反数\"},{\"label\":\"D\",\"value\":\"无法确定\"}]', '[\"#相反数\"]', 12, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:39');
INSERT INTO `tb_question` VALUES (17, 'polynomial-q03', 2, 4, '下列各式中，是多项式的是（ ）', '单选题', '简单', 'B', '多项式是若干个单项式的和。x²+2x+1 是多项式，3/x、√x、1/x² 分母含字母或根号，不是多项式，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/b375a818-cea3-48c0-92fd-8efae81d5f4d.mp4', 'https://tu.mianyazuju.com/2026/08/26/f5f8f655-4479-4664-99fe-c80a4be8802d.jpg', '00:18', '王老师', '本题讲解视频：下列各式中，是多项式的是（ ）', '[{\"label\":\"A\",\"value\":\"3/x\"},{\"label\":\"B\",\"value\":\"x²+2x+1\"},{\"label\":\"C\",\"value\":\"√x\"},{\"label\":\"D\",\"value\":\"1/x²\"}]', '[\"#整式\",\"#多项式\"]', 3, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:51');
INSERT INTO `tb_question` VALUES (18, 'polynomial-q04', 1, 5, '计算 (2x+1)-(x-3) 的结果是（ ）', '单选题', '中等', 'C', '去括号后合并同类项：(2x+1)-(x-3)=2x+1-x+3=x+4，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/62d42c83-1826-4437-ac91-13813fe44d81.mp4', 'https://tu.mianyazuju.com/2026/08/26/220785e2-370f-4ead-893e-0fef28d05dee.jpg', '00:18', '王老师', '本题讲解视频：计算 (2x+1)-(x-3) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"x-2\"},{\"label\":\"B\",\"value\":\"3x-2\"},{\"label\":\"C\",\"value\":\"x+4\"},{\"label\":\"D\",\"value\":\"x+2\"}]', '[\"#整式加减\"]', 4, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:04');
INSERT INTO `tb_question` VALUES (19, 'polynomial-q05', 2, 4, '单项式 -5xy² 的次数是（ ）', '单选题', '简单', 'D', '单项式的次数为所有字母指数之和：-5xy² 的次数为 1+2=3，故选 D。', 'https://tu.mianyazuju.com/2026/08/26/af02e28e-5ff2-4db6-bd71-6707ed9577fe.mp4', 'https://tu.mianyazuju.com/2026/08/26/3eeec6d4-ba2c-4caf-a237-67465f7a6779.jpg', '00:18', '王老师', '本题讲解视频：单项式 -5xy² 的次数是（ ）', '[{\"label\":\"A\",\"value\":\"1\"},{\"label\":\"B\",\"value\":\"2\"},{\"label\":\"C\",\"value\":\"-5\"},{\"label\":\"D\",\"value\":\"3\"}]', '[\"#单项式\",\"#次数\"]', 5, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:12');
INSERT INTO `tb_question` VALUES (20, 'polynomial-q06', 1, 5, '化简 2(a+b)-3(a-b) 的结果是（ ）', '单选题', '中等', 'A', '去括号并合并同类项：2(a+b)-3(a-b)=2a+2b-3a+3b=-a+5b，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/6c9c3926-0b63-4a9b-bf82-f8edb858a3b5.mp4', 'https://tu.mianyazuju.com/2026/08/26/6a889a54-5c0e-480f-bad4-1e9d817a18a2.jpg', '00:18', '王老师', '本题讲解视频：化简 2(a+b)-3(a-b) 的结果是（ ）', '[{\"label\":\"A\",\"value\":\"-a+5b\"},{\"label\":\"B\",\"value\":\"5a-b\"},{\"label\":\"C\",\"value\":\"-a-b\"},{\"label\":\"D\",\"value\":\"a+5b\"}]', '[\"#去括号\",\"#合并同类项\"]', 6, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:21');
INSERT INTO `tb_question` VALUES (21, 'mechanics-q03', 3, 7, '物体做匀速直线运动时，下列说法正确的是（ ）', '单选题', '中等', 'B', '匀速直线运动指速度大小和方向都不变的运动，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/f69a5569-a83e-43d0-ba8e-4b37480af4cf.mp4', 'https://tu.mianyazuju.com/2026/08/26/bb223f4b-5e5a-4c3c-9fb3-4829562e1d1c.jpg', '00:18', '王老师', '本题讲解视频：物体做匀速直线运动时，下列说法正确的是（ ）', '[{\"label\":\"A\",\"value\":\"速度会不断变化\"},{\"label\":\"B\",\"value\":\"速度大小和方向均不变\"},{\"label\":\"C\",\"value\":\"只有方向不变\"},{\"label\":\"D\",\"value\":\"只有大小不变\"}]', '[\"#运动学\",\"#匀速直线运动\"]', 3, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:53');
INSERT INTO `tb_question` VALUES (22, 'mechanics-q04', 3, 6, '力的三要素不包括（ ）', '单选题', '简单', 'D', '力的三要素是大小、方向、作用点；质量不是力的要素，故选 D。', 'https://tu.mianyazuju.com/2026/08/26/7656a1b4-f01f-4ca1-9668-00db021c2622.mp4', 'https://tu.mianyazuju.com/2026/08/26/94c67593-54e1-483c-8354-240616dbc0a6.jpg', '00:18', '王老师', '本题讲解视频：力的三要素不包括（ ）', '[{\"label\":\"A\",\"value\":\"大小\"},{\"label\":\"B\",\"value\":\"方向\"},{\"label\":\"C\",\"value\":\"作用点\"},{\"label\":\"D\",\"value\":\"质量\"}]', '[\"#力的概念\"]', 4, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:07');
INSERT INTO `tb_question` VALUES (23, 'mechanics-q05', 3, 7, '牛顿第一定律说明（ ）', '单选题', '中等', 'A', '牛顿第一定律说明物体具有惯性：不受外力时保持静止或匀速直线运动，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/8db10dec-2193-4a41-9689-023101c065e7.mp4', 'https://tu.mianyazuju.com/2026/08/26/9fc0cb68-6b8d-4e84-82fb-58abdd004399.jpg', '00:18', '王老师', '本题讲解视频：牛顿第一定律说明（ ）', '[{\"label\":\"A\",\"value\":\"物体具有惯性\"},{\"label\":\"B\",\"value\":\"力是维持运动的原因\"},{\"label\":\"C\",\"value\":\"力越大速度越大\"},{\"label\":\"D\",\"value\":\"静止的物体不受力\"}]', '[\"#牛顿第一定律\",\"#惯性\"]', 5, 1, '2026-08-19 13:44:24', '2026-08-26 10:49:15');
INSERT INTO `tb_question` VALUES (24, 'english-vm-q01', 4, 8, 'If I ____ you, I would study harder.', '单选题', '中等', 'C', '与现在事实相反的虚拟语气，if 从句中 be 动词用 were：If I were you, I would study harder. 故选 C。', 'https://tu.mianyazuju.com/2026/08/26/2c94c2b7-dd96-444c-b97d-dbee388f4dc1.mp4', 'https://tu.mianyazuju.com/2026/08/26/77c214cd-f103-4401-9cff-d604de402b6c.jpg', '00:18', '王老师', '本题讲解视频：If I ____ you, I would study harder.', '[{\"label\":\"A\",\"value\":\"am\"},{\"label\":\"B\",\"value\":\"was\"},{\"label\":\"C\",\"value\":\"were\"},{\"label\":\"D\",\"value\":\"be\"}]', '[\"#虚拟语气\",\"#固定搭配\"]', 1, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:21');
INSERT INTO `tb_question` VALUES (25, 'english-vm-q02', 4, 8, 'I wish I ____ taller.', '单选题', '中等', 'B', 'wish 后接与现在事实相反的虚拟语气，be 动词用 were：I wish I were taller. 故选 B。', 'https://tu.mianyazuju.com/2026/08/26/89bb154f-86f8-4b55-9a18-b711d0f5639a.mp4', 'https://tu.mianyazuju.com/2026/08/26/34e33a48-b945-473e-b45d-dcb402fe48e9.jpg', '00:18', '王老师', '本题讲解视频：I wish I ____ taller.', '[{\"label\":\"A\",\"value\":\"am\"},{\"label\":\"B\",\"value\":\"were\"},{\"label\":\"C\",\"value\":\"was\"},{\"label\":\"D\",\"value\":\"will be\"}]', '[\"#虚拟语气\",\"#wish从句\"]', 2, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:38');
INSERT INTO `tb_question` VALUES (26, 'coord-translate-q01', 6, 10, '在平面直角坐标系中，点 A 的坐标为（2, 3），将点 A 向左平移 3 个单位长度，再向下平移 2 个单位长度，得到点 B。则点 B 的坐标为（ ）', '单选题', '中等', 'A', '点向左平移横坐标减、向下平移纵坐标减：A(2,3) 左移 3 得 (-1,3)，再下移 2 得 B(-1,1)，故选 A。', 'https://tu.mianyazuju.com/2026/08/26/6f39533c-95ef-4a6c-83b5-838b483b2826.mp4', 'https://tu.mianyazuju.com/2026/08/26/c4bc0d45-dc22-475f-a32d-c33e12596440.jpg', '00:18', '王老师', '本题讲解视频：在平面直角坐标系中，点 A 的坐标为（2, 3），将点 A 向左平移 3 个单位', '[{\"label\":\"A\",\"value\":\"(-1, 1)\"},{\"label\":\"B\",\"value\":\"(5, 5)\"},{\"label\":\"C\",\"value\":\"(-1, 5)\"},{\"label\":\"D\",\"value\":\"(5, 1)\"}]', '[\"#坐标平移\",\"#平面直角坐标系\"]', 1, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:24');
INSERT INTO `tb_question` VALUES (27, 'linear-function-q01', 1, 10, '若一次函数 y = 2x + 1，当 x = 3 时，y 的值是（ ）', '单选题', '简单', 'C', '代入 x=3：y=2×3+1=7，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/eac8edf8-4cee-48fe-b70a-287c4f8b7255.mp4', 'https://tu.mianyazuju.com/2026/08/26/99d451fa-3976-46ff-8fc1-9e34a557dc2f.jpg', '00:18', '王老师', '本题讲解视频：若一次函数 y = 2x + 1，当 x = 3 时，y 的值是（ ）', '[{\"label\":\"A\",\"value\":\"5\"},{\"label\":\"B\",\"value\":\"6\"},{\"label\":\"C\",\"value\":\"7\"},{\"label\":\"D\",\"value\":\"8\"}]', '[\"#一次函数\",\"#代入求值\"]', 2, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:40');
INSERT INTO `tb_question` VALUES (28, 'linear-function-q02', 1, 10, '已知一次函数 y = kx + b 经过点 (0, 1) 和 (2, 5)，则 k 的值是（ ）', '单选题', '中等', 'B', '代入 (0,1) 得 b=1；代入 (2,5) 得 5=2k+1，解得 k=2，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/c6bdd5d9-4f9d-4e47-b7e9-0e9659546685.mp4', 'https://tu.mianyazuju.com/2026/08/26/9882189b-19b7-4191-9241-c7fa1b8945e7.jpg', '00:18', '王老师', '本题讲解视频：已知一次函数 y = kx + b 经过点 (0, 1) 和 (2, 5)，则', '[{\"label\":\"A\",\"value\":\"1\"},{\"label\":\"B\",\"value\":\"2\"},{\"label\":\"C\",\"value\":\"3\"},{\"label\":\"D\",\"value\":\"4\"}]', '[\"#一次函数\",\"#待定系数法\"]', 3, 1, '2026-08-19 13:44:24', '2026-08-26 10:48:56');
INSERT INTO `tb_question` VALUES (29, 'chinese-read-q01', 5, 9, '下列句子中，没有语病的一项是（ ）', '单选题', '中等', 'B', 'A「通过……使……」句式杂糅；C「能否……是……关键」两面对一面；D「大约……左右」重复；B 表述正确，故选 B。', 'https://tu.mianyazuju.com/2026/08/26/eed85ee1-c6b3-439b-8e69-a738f847dcc4.mp4', 'https://tu.mianyazuju.com/2026/08/26/254cb612-7907-40b9-b358-b40d6ddcc7c1.jpg', '00:18', '王老师', '本题讲解视频：下列句子中，没有语病的一项是（ ）', '[{\"label\":\"A\",\"value\":\"通过这次锻炼，使我的体质增强了。\"},{\"label\":\"B\",\"value\":\"我们要认真克服并随时发现学习中的缺点。\"},{\"label\":\"C\",\"value\":\"能否刻苦学习，是取得好成绩的关键。\"},{\"label\":\"D\",\"value\":\"他大约大概三十岁左右。\"}]', '[\"#语病辨析\",\"#阅读理解\"]', 1, 1, '2026-08-19 13:45:04', '2026-08-26 10:48:18');
INSERT INTO `tb_question` VALUES (30, 'chinese-read-q02', 5, 9, '《背影》的作者是（ ）', '单选题', '简单', 'C', '《背影》是朱自清的代表作，收录于散文集《背影》，故选 C。', 'https://tu.mianyazuju.com/2026/08/26/aa3650d4-1373-4295-a958-16f8944fce54.mp4', 'https://tu.mianyazuju.com/2026/08/26/61b5ef9e-f404-46cf-b0d2-477577471b31.jpg', '00:18', '刘老师', '本题讲解视频：《背影》的作者是（ ）', '[{\"label\":\"A\",\"value\":\"鲁迅\"},{\"label\":\"B\",\"value\":\"老舍\"},{\"label\":\"C\",\"value\":\"朱自清\"},{\"label\":\"D\",\"value\":\"冰心\"}]', '[\"#文学常识\",\"#现代文阅读\"]', 2, 1, '2026-08-19 13:45:04', '2026-08-26 10:48:35');
INSERT INTO `tb_question` VALUES (31, 'rational-numbers-multi-q01', 1, 1, '下列各数中，属于负数的有（  ）', '多选题', '中等', 'A,C', '-3 和 -1.5 均小于 0，属于负数；0 既不是正数也不是负数；2 是正数。', 'http://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', NULL, '03:10', '王老师', '多选题：逐项判断每个选项是否为负数。', '[{\"label\":\"A\",\"value\":\"-3\"},{\"label\":\"B\",\"value\":\"0\"},{\"label\":\"C\",\"value\":\"-1.5\"},{\"label\":\"D\",\"value\":\"2\"}]', '[\"#负数\",\"#有理数\",\"#多选题\"]', 13, 1, '2026-08-26 11:10:02', '2026-08-26 11:10:02');
INSERT INTO `tb_question` VALUES (32, 'rational-numbers-judge-q01', 1, 1, '0 是有理数。', '判断题', '简单', 'A', '有理数包括整数和分数，0 是整数，因此 0 是有理数，该说法正确。', 'http://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', NULL, '02:05', '王老师', '判断题：0 属于整数，整数是有理数的一部分。', '[{\"label\":\"A\",\"value\":\"正确\"},{\"label\":\"B\",\"value\":\"错误\"}]', '[\"#有理数\",\"#判断题\"]', 14, 1, '2026-08-26 11:10:02', '2026-08-26 11:10:02');
