  INDEX `idx_kefu_user_unread`(`user_id`, `sender_role`, `is_read`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '客服在线 IM 消息' ROW_FORMAT = Dynamic;

