-- ----------------------------
-- Table structure for tb_question_chapter
-- ----------------------------
DROP TABLE IF EXISTS `tb_question_chapter`;
CREATE TABLE `tb_question_chapter`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `chapter_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '章业务编码（对外查询键）',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '章标题',
  `grade` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '年级（如初中三年级）',
  `grade_short` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '年级简称（如初三）',
  `subject` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '学科',
  `version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '教材版本（如人教版）',
  `question_count` int(0) NOT NULL DEFAULT 0 COMMENT '章下题目总数',
  `sort_order` int(0) NOT NULL DEFAULT 0 COMMENT '排序（升序）',
  `state` tinyint(0) NOT NULL DEFAULT 1 COMMENT '状态：1启用 2禁用',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_chapter_code`(`chapter_code`) USING BTREE,
  INDEX `idx_chapter_filter`(`grade`, `subject`, `version`, `state`, `sort_order`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 220 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '题库-章' ROW_FORMAT = Dynamic;

