  `grade` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '年级',
  `grade_short` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '年级简称',
  `subject` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '学科',
  `question_count` int(0) NOT NULL DEFAULT 0 COMMENT '题目数量',
  `sort_order` int(0) NOT NULL DEFAULT 0 COMMENT '排序（升序）',
  `state` tinyint(0) NOT NULL DEFAULT 1 COMMENT '状态：1启用 2禁用',
