-- ----------------------------
-- Table structure for vip_plan
-- ----------------------------
DROP TABLE IF EXISTS `vip_plan`;
CREATE TABLE `vip_plan`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `month` int(0) NULL DEFAULT 1 COMMENT '月数',
  `amount` decimal(10, 2) NOT NULL COMMENT '会员价格',
  `original_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '原价',
  `sort` int(0) NULL DEFAULT 0,
  `status` tinyint(0) NOT NULL DEFAULT 1 COMMENT '1启用 0禁用',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '会员套餐' ROW_FORMAT = Dynamic;

