-- ----------------------------
-- Table structure for withdraw_record
-- ----------------------------
DROP TABLE IF EXISTS `withdraw_record`;
CREATE TABLE `withdraw_record`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(0) NOT NULL,
  `amount` decimal(12, 2) NOT NULL,
  `actual_amount` decimal(12, 2) NULL DEFAULT NULL COMMENT '实际到账',
  `service_fee` decimal(12, 2) NULL DEFAULT NULL COMMENT '手续费',
  `account_type` tinyint(0) NULL DEFAULT NULL COMMENT '1微信 2支付宝',
  `status` tinyint(0) NULL DEFAULT 0,
  `reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '拒绝理由',
  `withdraw_time` datetime(0) NULL DEFAULT NULL COMMENT '转账时间',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `update_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_withdraw_record_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '提现记录' ROW_FORMAT = Dynamic;

